import{_ as i,o as a,c as l,a2 as r}from"./chunks/framework.CqpfiAoK.js";const I=JSON.parse('{"title":"Этика Двойной Души","description":"","frontmatter":{},"headers":[],"relativePath":"ru/0058-双魂伦理准则.md","filePath":"ru/0058-双魂伦理准则.md"}'),d={name:"ru/0058-双魂伦理准则.md"};function e(o,t,h,n,s,b){return a(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="этика-двоинои-души" tabindex="-1">Этика Двойной Души <a class="header-anchor" href="#этика-двоинои-души" aria-label="Permalink to &quot;Этика Двойной Души&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>58</td></tr><tr><td>Модуль</td><td>Расы и формы жизни</td></tr><tr><td>Ключевые слова</td><td>Этика двух душ, права личности, достоинство души, баланс интересов, этическая экспертиза</td></tr></tbody></table><h2 id="i-постановка-проблемы-этики-двоинои-души" tabindex="-1">I. Постановка проблемы этики двойной души <a class="header-anchor" href="#i-постановка-проблемы-этики-двоинои-души" aria-label="Permalink to &quot;I. Постановка проблемы этики двойной души&quot;">​</a></h2><p>Проблема этики двойной души — фундаментальная этическая проблема, которую Симбиотическая Цивилизация Якоря должна решить перед лицом тёмных замещающих сущностей (см. <em>57-黑暗置换体起源与本质</em>). Когда в одном теле находятся две независимые души — исходная хозяйская душа и тёмная замещающая душа — возникает ряд глубоких этических проблем:</p><ul><li>Обладают ли обе души независимыми правами личности?</li><li>Преимущественны ли права исходной хозяйской души перед правами тёмной замещающей души?</li><li>Морально ли уничтожить тёмную замещающую душу ради защиты исходной хозяйской души?</li><li>Когда интересы двух душ конфликтуют, как их следует взвешивать?</li><li>Обязано ли общество вкладывать ресурсы в спасение исходных хозяйской душ, подвергшихся тёмному замещению?</li><li>Имеет ли тёмная замещающая душа «право на существование»?</li></ul><p>На эти проблемы нет простых ответов; для руководства практикой необходимо создать систематические этические принципы. Этика Двойной Души — именно тот нормативный документ, который разработан в ответ на эти проблемы, и он является этической основой идентификации, лечения и обращения с тёмными замещающими сущностями.</p><h2 id="ii-основные-принципы-этики-двоинои-души" tabindex="-1">II. Основные принципы этики двойной души <a class="header-anchor" href="#ii-основные-принципы-этики-двоинои-души" aria-label="Permalink to &quot;II. Основные принципы этики двойной души&quot;">​</a></h2><p>Этика Двойной Души устанавливает следующие шесть основных принципов как ценностный краеугольный камень для решения проблем двух душ:</p><table tabindex="0"><thead><tr><th>Принцип</th><th>Содержание</th></tr></thead><tbody><tr><td>Принцип достоинства души</td><td>Каждая душа с независимым сознанием обладает врождённым достоинством и не должна произвольно уничтожаться или порабощаться</td></tr><tr><td>Принцип приоритета исходной души</td><td>В конфликтах двух душ законные права исходной хозяйской души преимущественны перед правами тёмной замещающей души, поскольку исходный хозяин — законный владелец тела</td></tr><tr><td>Принцип наименьшего вреда</td><td>При решении проблем двух душ следует выбирать вариант, наносящий наименьший вред всем заинтересованным сторонам, по возможности избегая уничтожения душ</td></tr><tr><td>Принцип пропорциональности</td><td>Принимаемые меры должны соответствовать степени риска сущности двух душ ; чрезмерное обращение запрещено</td></tr><tr><td>Принцип информированного согласия</td><td>Когда исходная хозяйская душа может выразить свою волю, крупные решения, касающиеся тела и души исходного хозяина, должны получать его согласие</td></tr><tr><td>Принцип максимального спасения</td><td>Общество обязано в разумных пределах прилагать все усилия для спасения исходных хозяйской душ, подвергшихся тёмному замещению, и не должно легко отказываться</td></tr></tbody></table><h2 id="iii-определение-прав-личности-двух-душ" tabindex="-1">III. Определение прав личности двух душ <a class="header-anchor" href="#iii-определение-прав-личности-двух-душ" aria-label="Permalink to &quot;III. Определение прав личности двух душ&quot;">​</a></h2><p>Первоочередная проблема этики двойной души — определение прав личности двух душ. Настоящая Этика устанавливает следующие правила определения:</p><h3 id="i-права-личности-исходнои-хозяискои-души" tabindex="-1">(I) Права личности исходной хозяйской души <a class="header-anchor" href="#i-права-личности-исходнои-хозяискои-души" aria-label="Permalink to &quot;(I) Права личности исходной хозяйской души&quot;">​</a></h3><p>Исходная хозяйская душа — законный владелец тела, и её права личности полностью признаются и защищаются:</p><ol><li>Исходная хозяйская душа пользуется всеми основными правами, предоставленными Симбиотической Конституцией, включая право на жизнь, право на телесную неприкосновенность, право на здоровье, право на личное достоинство и т.д.</li><li>Исходная хозяйская душа обладает окончательным правом решения в отношении своего тела ; когда она может выразить свою волю, любое крупное обращение с телом должно получать согласие исходного хозяина.</li><li>Законные права и интересы исходной хозяйской души, такие как имущественные права, права идентичности и социальные отношения, защищаются законом и не утрачиваются из-за тёмного замещения.</li><li>Исходная хозяйская душа имеет право на социальную помощь и поддержку, включая очищающее лечение, юридическую помощь, психологическое консультирование и т.д.</li><li>Даже при глубоком подавлении права личности исходной хозяйской души сохраняются ; её нельзя объявить умершей или лишить прав.</li></ol><h3 id="ii-права-личности-темнои-замещающеи-души" tabindex="-1">(II) Права личности тёмной замещающей души <a class="header-anchor" href="#ii-права-личности-темнои-замещающеи-души" aria-label="Permalink to &quot;(II) Права личности тёмной замещающей души&quot;">​</a></h3><p>Определение прав личности тёмной замещающей души относительно сложно ; настоящая Этика занимает позицию «ограниченного признания»:</p><table tabindex="0"><thead><tr><th>Стадия развития</th><th>Определение прав личности</th><th>Объём прав</th></tr></thead><tbody><tr><td>Период энергетического разъедания (Первая стадия)</td><td>Не имеет независимой личности</td><td>Независимая душа ещё не сформировалась ; нет независимых прав личности</td></tr><tr><td>Период загрязнения души (Вторая стадия)</td><td>Не имеет независимой личности</td><td>Всё ещё загрязнённое состояние исходной хозяйской души ; нет независимых прав личности</td></tr><tr><td>Период формирования двух душ (Третья стадия)</td><td>Ограниченные права личности</td><td>Имеет предварительное независимое сознание, пользуется основными правами достоинства души, но не пользуется правами контроля тела и полными гражданскими правами</td></tr><tr><td>Период тёмного доминирования (Четвёртая стадия)</td><td>Ограниченные права личности</td><td>Имеет полностью независимое сознание, пользуется правами достоинства души и правом на уважительное отношение, но из-за своей опасности её права подвергаются необходимым ограничениям</td></tr><tr><td>Период полного замещения (Пятая стадия)</td><td>Полные права личности (но как враждебное существование)</td><td>Исходный хозяин погиб, тёмная душа становится единственной душой тела, с полными правами личности, но из-за её враждебного поведения могут применяться принудительные меры, включая уничтожение, в соответствии с законом</td></tr></tbody></table><h3 id="iii-конкретное-содержание-ограниченных-прав-личности" tabindex="-1">(III) Конкретное содержание ограниченных прав личности <a class="header-anchor" href="#iii-конкретное-содержание-ограниченных-прав-личности" aria-label="Permalink to &quot;(III) Конкретное содержание ограниченных прав личности&quot;">​</a></h3><p>Ограниченные права личности, которыми пользуется тёмная замещающая душа на третьей и четвёртой стадиях, включают:</p><ol><li><strong>Право на достоинство души</strong> : не должна подвергаться оскорблению, жестокому обращению или пыткам ; базовое уважение должно сохраняться даже при контроле и обращении.</li><li><strong>Право на безболезненное уничтожение</strong> : если окончательно решено уничтожить тёмную замещающую душу, следует применить безболезненный и быстрый способ, уменьшив её страдания.</li><li><strong>Право выражения</strong> : в безопасных и контролируемых условиях тёмная замещающая душа имеет право выражать свою волю и позицию, но её выражение не имеет юридической обязательной силы.</li><li><strong>Право быть выслушанной</strong> : при принятии крупных решений, затрагивающих тёмную замещающую душу, её мнение должно выслушиваться в разумных пределах.</li></ol><p>Тёмная замещающая душа не пользуется следующими правами : правами контроля тела, свободой передвижения, политическими правами гражданина, правом собственности (имущество исходного хозяина принадлежит исходному хозяину) и правом на воспроизводство (для предотвращения распространения тёмных кровей).</p><h2 id="iv-правила-взвешивания-конфликтов-интересов-двух-душ" tabindex="-1">IV. Правила взвешивания конфликтов интересов двух душ <a class="header-anchor" href="#iv-правила-взвешивания-конфликтов-интересов-двух-душ" aria-label="Permalink to &quot;IV. Правила взвешивания конфликтов интересов двух душ&quot;">​</a></h2><p>Когда интересы исходной хозяйской души и тёмной замещающей души конфликтуют, они взвешиваются по следующим правилам:</p><h3 id="i-типы-конфликтов-и-правила-взвешивания" tabindex="-1">(I) Типы конфликтов и правила взвешивания <a class="header-anchor" href="#i-типы-конфликтов-и-правила-взвешивания" aria-label="Permalink to &quot;(I) Типы конфликтов и правила взвешивания&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Тип конфликта</th><th>Правило взвешивания</th></tr></thead><tbody><tr><td>Конфликт прав на выживание (выживание одной стороны обусловлено гибелью другой)</td><td>Право на выживание исходной хозяйской души преимущественно ; при невозможности сосуществования в первую очередь защищается выживание исходного хозяина</td></tr><tr><td>Конфликт прав контроля тела</td><td>Исходная хозяйская душа имеет окончательное право контроля над телом ; право контроля тела тёмной души строго ограничено</td></tr><tr><td>Конфликт прав выражения</td><td>Выражение исходной хозяйской души имеет юридическую обязательную силу ; выражение тёмной души служит только справочным материалом</td></tr><tr><td>Конфликт имущественных прав</td><td>Тело и имущество принадлежат исходному хозяину ; тёмная душа не имеет имущественных прав</td></tr><tr><td>Конфликт прав выбора лечения</td><td>Исходная хозяйская душа имеет право выбирать, принимать ли очищающее лечение ; тёмная душа не имеет права препятствовать</td></tr><tr><td>Конфликт метода обращения</td><td>Для обращений, связанных с уничтожением тёмной души, воля исходной хозяйской души играет решающую роль (но должна пройти этическую экспертизу)</td></tr></tbody></table><h3 id="ii-уважение-и-ограничение-воли-исходного-хозяина" tabindex="-1">(II) Уважение и ограничение воли исходного хозяина <a class="header-anchor" href="#ii-уважение-и-ограничение-воли-исходного-хозяина" aria-label="Permalink to &quot;(II) Уважение и ограничение воли исходного хозяина&quot;">​</a></h3><p>Когда исходная хозяйская душа может выразить свою волю, воля исходного хозяина должна полностью уважаться, со следующими исключениями:</p><ol><li>Воли исходного хозяина, явно наносящие вред общественной безопасности или законным правам и интересам других, не защищаются.</li><li>Выражения воли, сделанные исходным хозяином под влиянием тёмной души, не являющиеся подлинными, не имеют юридической силы.</li><li>Если исходный хозяин добровольно выбирает слияние с тёмной душой, следует провести строгую этическую экспертизу и оценку рисков, подтвердив, что существование после слияния не будет представлять угрозу для общества.</li><li>Если исходный хозяин добровольно выбирает отказ от лечения и принятие полного замещения тёмной душой, общество должно вмешаться и убедить, но при полной ясности сознания и неоднократном подтверждении исходным хозяином его автономное право решения должно в конечном счёте уважаться (это этическая серая зона, требующая индивидуальной экспертизы).</li></ol><h2 id="v-механизм-этическои-экспертизы-двоинои-души" tabindex="-1">V. Механизм этической экспертизы двойной души <a class="header-anchor" href="#v-механизм-этическои-экспертизы-двоинои-души" aria-label="Permalink to &quot;V. Механизм этической экспертизы двойной души&quot;">​</a></h2><p>Для обеспечения соответствия решения проблем двух душ этическим принципам государство создаёт механизм этической экспертизы двойной души:</p><h3 id="i-комитет-этическои-экспертизы" tabindex="-1">(I) Комитет этической экспертизы <a class="header-anchor" href="#i-комитет-этическои-экспертизы" aria-label="Permalink to &quot;(I) Комитет этической экспертизы&quot;">​</a></h3><ul><li><strong>Состав</strong> : состоит из этиков, юристов, учёных в области наук о жизни, культиваторов, представителей инородных рас и представителей общественности ; эксперты с опытом исследования или лечения тёмных замещающих сущностей должны составлять не менее одной трети.</li><li><strong>Функции</strong> : проводить экспертизу и выносить решения по крупным этическим проблемам, связанным с двумя душами, включая решения об уничтожении тёмной души, одобрение слияния двух душ и определение действительности воли исходного хозяина.</li><li><strong>Независимость</strong> : Комитет этической экспертизы осуществляет свои полномочия независимо, без вмешательства административных органов и частных лиц.</li><li><strong>Процедура</strong> : экспертиза проводится в форме слушаний, решения выносятся после выслушивания мнений исходного хозяина (если он может выразиться), лечащей команды, членов семьи, представителей общества и всех сторон.</li></ul><h3 id="ii-вопросы-подлежащие-обязательнои-этическои-экспертизе" tabindex="-1">(II) Вопросы, подлежащие обязательной этической экспертизе <a class="header-anchor" href="#ii-вопросы-подлежащие-обязательнои-этическои-экспертизе" aria-label="Permalink to &quot;(II) Вопросы, подлежащие обязательной этической экспертизе&quot;">​</a></h3><p>Следующие вопросы должны быть рассмотрены и одобрены Комитетом этической экспертизы двойной души до их осуществления:</p><ol><li>Осуществление обращения, уничтожающего тёмную душу, для тёмных замещающих сущностей на третьей и четвёртой стадиях.</li><li>Осуществление операции по слиянию двух душ на тёмных замещающих сущностях.</li><li>Осуществление операции по разделению душ на тёмных замещающих сущностях.</li><li>Принятие окончательных решений об обращении с тёмными замещающими сущностями, воля исходного хозяина которых — отказ от лечения.</li><li>Осуществление планов лечения, способных повредить исходную хозяйскую душу.</li><li>Проведение научных исследований, затрагивающих душу, на тёмных замещающих сущностях.</li><li>Другие вопросы, связанные с крупными этическими проблемами двух душ.</li></ol><h2 id="vi-социальные-права-и-обязанности-сущностеи-двух-душ" tabindex="-1">VI. Социальные права и обязанности сущностей двух душ <a class="header-anchor" href="#vi-социальные-права-и-обязанности-сущностеи-двух-душ" aria-label="Permalink to &quot;VI. Социальные права и обязанности сущностей двух душ&quot;">​</a></h2><h3 id="i-социальные-права" tabindex="-1">(I) Социальные права <a class="header-anchor" href="#i-социальные-права" aria-label="Permalink to &quot;(I) Социальные права&quot;">​</a></h3><p>Пока исходная хозяйская душа ещё существует, сущность двух душ (тёмная замещающая сущность) пользуется следующими социальными правами:</p><ol><li>Право на базовое жизнеобеспечение и медицинскую помощь.</li><li>Право на юридическую помощь и этическое консультирование.</li><li>Право на контакт с родственниками и друзьями в безопасных и контролируемых условиях.</li><li>Право на образование и участие в культурных мероприятиях (в изоляционных учреждениях).</li><li>Право на обжалование и пересмотр решений об обращении.</li></ol><h3 id="ii-социальные-обязанности-и-ограничения" tabindex="-1">(II) Социальные обязанности и ограничения <a class="header-anchor" href="#ii-социальные-обязанности-и-ограничения" aria-label="Permalink to &quot;(II) Социальные обязанности и ограничения&quot;">​</a></h3><p>Сущность двух душ одновременно несёт следующие обязанности и ограничения:</p><ol><li>Обязанность принять изоляционный контроль и лечение.</li><li>Обязанность не нападать на другие формы жизни и не заражать их (нарушители будут подвергнуты более строгому контролю).</li><li>Обязанность сотрудничать с идентификационной оценкой и мониторингом.</li><li>Свобода передвижения строго ограничена ; до излечения нельзя покидать изоляционное учреждение.</li><li>Нельзя заниматься культивацией, распространением тёмной энергии или другими видами деятельности, способными усилить замещение.</li></ol><h2 id="vii-передовые-спорные-вопросы-этики-двоинои-души" tabindex="-1">VII. Передовые спорные вопросы этики двойной души <a class="header-anchor" href="#vii-передовые-спорные-вопросы-этики-двоинои-души" aria-label="Permalink to &quot;VII. Передовые спорные вопросы этики двойной души&quot;">​</a></h2><p>В области этики двойной души остаются передовые спорные вопросы, по которым ещё не достигнут консенсус и которые требуют постоянного исследования на практике:</p><ol><li><strong>Проблема «первородного греха» тёмной души</strong> : тёмная замещающая душа разрушительна с рождения. Означает ли это, что она по своей природе «злая»? Возможно ли существование «доброй» тёмной души?</li><li><strong>Этическая легитимность слияния душ</strong> : новая душа, созданная слиянием двух душ, не является ни исходным хозяином, ни тёмной душой. Как определить этический статус этого «третьего существования»?</li><li><strong>Предел вложения ресурсов</strong> : сколько ресурсов общество должно вкладывать в спасение исходной хозяйской души внутри тёмной замещающей сущности? Когда стоимость спасения чрезвычайно высока, а вероятность успеха чрезвычайно низка, сохраняется ли обязанность прилагать максимальные усилия?</li><li><strong>Возможность перевоспитания тёмной души</strong> : можно ли перевоспитать тёмную душу в неразрушительное существование посредством образования, исправления, энергетической трансформации и других средств? Если да, должна ли перевоспитанная тёмная душа получить полные права личности?</li><li><strong>Баланс профилактики и приватности</strong> : для предотвращения возникновения тёмных замещающих сущностей допустимо ли проводить мониторинг воздействия Бездонной Энергии на живые существа? Нарушает ли такой мониторинг приватность души?</li></ol><p>Эти спорные вопросы постоянно изучаются научно-исследовательскими институтами этики двойной души ; Комитет этической экспертизы выносит решения по отдельным случаям согласно конкретным обстоятельствам, и соответствующие выводы будут постоянно обновлять настоящую Этику.</p><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Этика Двойной Души — глубокое проявление жизненной этики Симбиотической Цивилизации Якоря. Устанавливая основные принципы достоинства души, приоритета исходной души и наименьшего вреда, определяя границы прав личности двух душ и создавая правила взвешивания конфликтов интересов и механизмы этической экспертизы, она обеспечивает прочную этическую основу для управления тёмными замещающими сущностями. Центральный дух этики двойной души : даже перед лицом самого опасного врага не отказываться от твёрдой защиты достоинства жизни ; даже под самой неотложной угрозой безопасности не переступать этическую линию. Именно это — фундаментальный признак, отличающий симбиотическую цивилизацию от хищнической цивилизации.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>57-黑暗置换体起源与本质 (Происхождение и сущность тёмных замещающих сущностей)</li><li>59-黑暗置换体四类分支处置 (Обращение с четырьмя ветвями тёмных замещающих сущностей)</li><li>48-司法体系与裁决机制 (Судебная система и механизм решений)</li><li>40-共生宪法总纲 (Общая программа Симбиотической Конституции)</li></ul>',50)])])}const c=i(d,[["render",e]]);export{I as __pageData,c as default};
